theorem format_error_bound_of_le (F : FloatFormat) (r : RoundOp F) {x M : ℝ}
    (hx : |x| ≤ M) :
    |roundToFormat F r x - x| ≤ F.eps * M + F.tiny

theorem round_close (F : FloatFormat) (r : RoundOp F) {x y η : ℝ}
    (h : |x - y| ≤ η) :
    |roundToFormat F r x - y| ≤ F.eps * |x| + F.tiny + η
